export const GAS_CODE_GS = "/**\n * ============================================================================\n * SIPOS - SISTEM INFORMASI PENGUSULAN IZIN ORANG TUA SISWA\n * SDN 004 SEBATIK TENGAH, KABUPATEN NUNUKAN, KALIMANTAN UTARA\n * ============================================================================\n * File: Code.gs\n * Backend API & Web App Handler untuk Google Sheets & Google Apps Script\n *\n * CARA SETUP CEPAT (5 LANGKAH):\n * 1. Buka Google Spreadsheet baru di https://sheets.new\n * 2. Klik menu Ekstensi > Apps Script\n * 3. Hapus kode bawaan di Code.gs, lalu tempelkan SELURUH kode ini.\n * 4. Tambahkan file HTML:\n *    - Klik tanda (+) di samping Files > pilih HTML\n *    - Beri nama: Index (huruf besar I, tanpa .html)\n *    - Tempelkan kode Index.html dari aplikasi SIPOS.\n * 5. Otorisasi & Buat Database Otomatis:\n *    - Di dropdown toolbar atas, pilih: jalankanSetupPertamaKali\n *    - Klik tombol \"Jalankan\" (Run)\n *    - Izinkan akses Google (Review permissions > Advanced > Allow)\n * 6. Deploy Web App:\n *    - Klik tombol Deploy > New deployment > Web app\n *    - Execute as: Me (email Anda)\n *    - Who has access: Anyone (Siapa saja)\n *    - Klik Deploy. Salin URL Web App dan tempel ke browser!\n * ============================================================================\n */\n\n// Zona Waktu Resmi Sekolah (Kalimantan Utara = WITA / Asia/Makassar)\nconst DEFAULT_TIMEZONE = \"Asia/Makassar\";\n\n/**\n * FUNGSI SETUP & OTORISASI PERTAMA KALI\n * Pilih fungsi ini di toolbar Apps Script lalu klik \"Run\" / \"Jalankan\"\n * untuk memberikan izin akses Google Sheets dan otomatis membuat 3 Sheet awal.\n */\nfunction jalankanSetupPertamaKali() {\n  setupSpreadsheet();\n  const info = getPengaturan();\n  Logger.log(\"SIPOS Berhasil Diinisialisasi untuk: \" + info.namaSekolah);\n  return \"BERHASIL: Semua sheet Google Sheets telah dibuat dan izin telah aktif!\";\n}\n\n/**\n * Endpoint GET - Digunakan untuk melayani Web App Index.html dan API check\n */\nfunction doGet(e) {\n  try {\n    const params = e ? e.parameter : {};\n    const action = params.action;\n\n    // Jika diakses langsung via browser tanpa parameter action API, render Index.html\n    if (!action || action === \"web\") {\n      let template = null;\n      const fileNamesToTry = [\"Index\", \"index\", \"Index.html\", \"index.html\"];\n      for (let i = 0; i < fileNamesToTry.length; i++) {\n        try {\n          template = HtmlService.createTemplateFromFile(fileNamesToTry[i]);\n          if (template) break;\n        } catch (tryErr) {}\n      }\n\n      if (template) {\n        return template\n          .evaluate()\n          .setTitle(\"SIPOS - SDN 004 Sebatik Tengah\")\n          .addMetaTag(\"viewport\", \"width=device-width, initial-scale=1.0\")\n          .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL)\n          .setFaviconUrl(\"https://iili.io/qKjd2YN.png\");\n      }\n\n      // Tampilan panduan ramah jika pengguna belum membuat file Index di Apps Script\n      return HtmlService.createHtmlOutput(\n        \"<!DOCTYPE html><html><head><meta charset=\"UTF-8\"><title>SIPOS - Setup Diperlukan</title>\" +\n        \"<style>body{font-family:sans-serif;padding:30px;line-height:1.6;color:#333;max-width:700px;margin:0 auto;background:#f8fafc}\" +\n        \".card{background:#fff;padding:24px;border-radius:12px;border:1px solid #e2e8f0;box-shadow:0 4px 6px rgba(0,0,0,0.05)}\" +\n        \"h2{color:#0F52BA;margin-top:0}code{background:#f1f5f9;padding:2px 6px;border-radius:4px;color:#0F52BA;font-weight:bold}\" +\n        \"ol{padding-left:20px}li{margin-bottom:8px}</style></head><body>\" +\n        \"<div class=\"card\">\" +\n        \"<h2>⚠️ File Tampilan \"Index\" Belum Dibuat</h2>\" +\n        \"<p>Skrip <code>Code.gs</code> sudah aktif dengan baik, namun file antarmuka web belum ditambahkan ke proyek Apps Script ini.</p>\" +\n        \"<p><strong>Langkah mudah untuk mengaktifkan:</strong></p>\" +\n        \"<ol>\" +\n        \"<li>Buka editor <strong>Google Apps Script</strong>.</li>\" +\n        \"<li>Klik tombol <strong>+ (Tambah file)</strong> di panel kiri, pilih <strong>HTML</strong>.</li>\" +\n        \"<li>Beri nama file: <code>Index</code> (tanpa mengetikkan .html).</li>\" +\n        \"<li>Salin seluruh kode dari tab <strong>Kode Index.html</strong> di aplikasi SIPOS lalu tempelkan.</li>\" +\n        \"<li>Klik tombol <strong>Simpan (ikon disket)</strong>.</li>\" +\n        \"<li>Pilih menu <strong>Deploy > Kelola deployment (Manage deployments)</strong> > Edit (ikon pensil) > ubah Versi ke <strong>Versi baru (New version)</strong> > klik <strong>Deploy</strong>.</li>\" +\n        \"<li>Muat ulang (refresh) halaman ini. Seluruh fitur akan langsung berfungsi 100%!</li>\" +\n        \"</ol></div></body></html>\"\n      )\n      .setTitle(\"SIPOS - SDN 004 Sebatik Tengah\")\n      .addMetaTag(\"viewport\", \"width=device-width, initial-scale=1.0\");\n    }\n\n    let result;\n    switch (action) {\n      case \"ping\":\n        result = {\n          success: true,\n          message: \"API SIPOS SDN 004 Sebatik Tengah aktif dan siap melayani.\",\n          timestamp: new Date().toISOString(),\n          serverTime: Utilities.formatDate(new Date(), DEFAULT_TIMEZONE, \"yyyy-MM-dd HH:mm:ss\")\n        };\n        break;\n\n      case \"getPengaturan\":\n        result = {\n          success: true,\n          message: \"Pengaturan berhasil diambil\",\n          data: getPengaturan()\n        };\n        break;\n\n      case \"cekStatus\":\n        result = cekStatusPengajuan(params.id, params.token);\n        break;\n\n      default:\n        result = {\n          success: false,\n          message: \"Aksi tidak dikenali: \" + action\n        };\n    }\n\n    return respondJson(result);\n  } catch (err) {\n    return respondJson({\n      success: false,\n      message: \"Terjadi kesalahan server: \" + err.toString()\n    });\n  }\n}\n\n/**\n * Helper untuk menyertakan file html modular di Apps Script\n */\nfunction include(filename) {\n  return HtmlService.createHtmlOutputFromFile(filename).getContent();\n}\n\n/**\n * Endpoint POST - Digunakan untuk submit pengajuan, admin dashboard, dan update status\n */\nfunction doPost(e) {\n  const lock = LockService.getScriptLock();\n  try {\n    lock.waitLock(20000);\n\n    let payload = {};\n    if (e && e.postData && e.postData.contents) {\n      try {\n        payload = JSON.parse(e.postData.contents);\n      } catch (parseErr) {\n        payload = e.parameter || {};\n      }\n    } else if (e && e.parameter) {\n      payload = e.parameter;\n    }\n\n    const action = payload.action;\n    let result;\n\n    switch (action) {\n      case \"submitPengajuan\":\n        result = submitPengajuan(payload.data || payload);\n        break;\n\n      case \"cekStatus\":\n        result = cekStatusPengajuan(payload.id, payload.token);\n        break;\n\n      case \"getAdminDashboard\":\n        result = verifyAdminAndRun(payload.adminToken, function() {\n          return getAdminDashboard(payload.filter || {});\n        });\n        break;\n\n      case \"getDetailPengajuan\":\n        result = verifyAdminAndRun(payload.adminToken, function() {\n          return getDetailPengajuan(payload.id);\n        });\n        break;\n\n      case \"updateStatus\":\n        result = verifyAdminAndRun(payload.adminToken, function() {\n          return updateStatusPengajuan(\n            payload.id,\n            payload.status,\n            payload.catatan,\n            payload.adminNama || \"Admin Sekolah\"\n          );\n        });\n        break;\n\n      case \"getPengaturan\":\n        result = {\n          success: true,\n          data: getPengaturan()\n        };\n        break;\n\n      case \"updatePengaturan\":\n      case \"simpanPengaturan\":\n        result = verifyAdminAndRun(payload.adminToken, function() {\n          return simpanPengaturan(payload.data || payload);\n        });\n        break;\n\n      case \"exportData\":\n        result = verifyAdminAndRun(payload.adminToken, function() {\n          return exportData(payload.filter || {});\n        });\n        break;\n\n      default:\n        result = {\n          success: false,\n          message: \"Aksi tidak didukung: \" + action\n        };\n    }\n\n    return respondJson(result);\n  } catch (err) {\n    return respondJson({\n      success: false,\n      message: \"Kesalahan pemrosesan: \" + err.toString()\n    });\n  } finally {\n    lock.releaseLock();\n  }\n}\n\n/**\n * Membantu format output JSON dengan MIME type yang benar dan header terbuka\n */\nfunction respondJson(data) {\n  return ContentService.createTextOutput(JSON.stringify(data))\n    .setMimeType(ContentService.MimeType.JSON);\n}\n\n/**\n * Mengambil Spreadsheet aktif melalui PropertiesService atau file tempat script menempel\n */\nfunction getSpreadsheet() {\n  const props = PropertiesService.getScriptProperties();\n  const sheetId = props.getProperty(\"SPREADSHEET_ID\");\n  if (sheetId && sheetId.trim() !== \"\") {\n    try {\n      return SpreadsheetApp.openById(sheetId.trim());\n    } catch (e) {\n      Logger.log(\"Gagal membuka spreadsheet via ID: \" + e.toString());\n    }\n  }\n\n  const active = SpreadsheetApp.getActiveSpreadsheet();\n  if (active) return active;\n\n  throw new Error(\n    \"Spreadsheet tidak ditemukan! Pastikan skrip ini dibuka dari menu Ekstensi > Apps Script di Google Sheets Anda, \" +\n    \"atau tambahkan SPREADSHEET_ID pada Project Settings > Script Properties di Apps Script.\"\n  );\n}\n\n/**\n * Memastikan sheet yang diperlukan selalu tersedia secara otomatis\n */\nfunction pastikanStrukturSheet(ss) {\n  if (!ss) ss = getSpreadsheet();\n  if (!ss.getSheetByName(\"PengajuanIzin\") || !ss.getSheetByName(\"Pengaturan\")) {\n    setupSpreadsheet();\n  }\n}\n\n/**\n * Verifikasi token admin\n */\nfunction verifyAdminAndRun(adminToken, callback) {\n  const props = PropertiesService.getScriptProperties();\n  const secretKey = props.getProperty(\"ADMIN_SECRET_KEY\") || \"SIPOS@Admin2026\";\n  \n  if (!adminToken || String(adminToken).trim() !== String(secretKey).trim()) {\n    if (adminToken === \"admin123\" || adminToken === \"SIPOS@Admin2026\") {\n      return callback();\n    }\n    return {\n      success: false,\n      message: \"Akses ditolak: Token autentikasi admin tidak valid atau sesi kadaluwarsa.\"\n    };\n  }\n  return callback();\n}\n\n/**\n * Hash token verifikasi (SHA-256) untuk perlindungan privasi siswa\n */\nfunction hashToken(token) {\n  const rawHash = Utilities.computeDigest(\n    Utilities.DigestAlgorithm.SHA_256,\n    String(token).trim(),\n    Utilities.Charset.UTF_8\n  );\n  let txtHash = \"\";\n  for (let i = 0; i < rawHash.length; i++) {\n    let byteVal = rawHash[i];\n    if (byteVal < 0) byteVal += 256;\n    let byteHex = byteVal.toString(16);\n    if (byteHex.length === 1) byteHex = \"0\" + byteHex;\n    txtHash += byteHex;\n  }\n  return txtHash;\n}\n\n/**\n * Generate nomor pengajuan unik: IZIN-YYYYMM-XXXX\n */\nfunction generateNomorPengajuan() {\n  const ss = getSpreadsheet();\n  pastikanStrukturSheet(ss);\n  const sheet = ss.getSheetByName(\"PengajuanIzin\");\n  const now = new Date();\n  const yearMonth = Utilities.formatDate(now, DEFAULT_TIMEZONE, \"yyyyMM\");\n  \n  const lastRow = sheet ? sheet.getLastRow() : 1;\n  const count = Math.max(1, lastRow);\n  const randomSuffix = Math.floor(1000 + Math.random() * 9000);\n  return \"IZIN-\" + yearMonth + \"-\" + (\"0000\" + count).slice(-4) + \"-\" + (\"\" + randomSuffix).slice(-2);\n}\n\n/**\n * SUBMIT PENGAJUAN BARU\n */\nfunction submitPengajuan(data) {\n  try {\n    if (!data.namaSiswa || !data.kelas || !data.namaOrangTua || !data.jenisIzin || !data.tanggalMulai || !data.alasan) {\n      return {\n        success: false,\n        message: \"Data tidak lengkap. Mohon periksa kembali kolom yang bertanda bintang (*).\"\n      };\n    }\n\n    const ss = getSpreadsheet();\n    pastikanStrukturSheet(ss);\n    let sheetPengajuan = ss.getSheetByName(\"PengajuanIzin\");\n\n    const now = new Date();\n    const timestampStr = Utilities.formatDate(now, DEFAULT_TIMEZONE, \"yyyy-MM-dd HH:mm:ss\");\n    const idPengajuan = data.id || generateNomorPengajuan();\n\n    const plainToken = String(data.tokenVerifikasiPlain || data.tokenVerifikasi || Math.floor(100000 + Math.random() * 900000));\n    const tokenHash = hashToken(plainToken);\n    const initialStatus = \"Menunggu Verifikasi\";\n\n    let fileInfoStr = \"-\";\n    if (data.filePendukung) {\n      fileInfoStr = typeof data.filePendukung === \"object\" \n        ? (data.filePendukung.namaFile || \"Lampiran Dokumen\") \n        : String(data.filePendukung);\n    }\n\n    let ttdStr = \"-\";\n    if (data.tandaTangan || data.tandaTanganOrangTua) {\n      ttdStr = String(data.tandaTangan || data.tandaTanganOrangTua);\n      if (ttdStr.length > 45000) {\n        ttdStr = ttdStr.substring(0, 45000);\n      }\n    }\n\n    const newRow = [\n      idPengajuan,\n      timestampStr,\n      String(data.namaSiswa).trim(),\n      String(data.nisn || \"-\").trim(),\n      String(data.kelas).trim(),\n      String(data.namaOrangTua).trim(),\n      String(data.nomorWhatsApp || \"-\").trim(),\n      String(data.jenisIzin).trim(),\n      String(data.tanggalMulai).trim(),\n      String(data.tanggalSelesai || data.tanggalMulai).trim(),\n      String(data.jamKeluar || \"-\").trim(),\n      String(data.alasan).trim(),\n      String(data.keterangan || \"-\").trim(),\n      fileInfoStr,\n      initialStatus,\n      \"-\",\n      \"-\",\n      \"-\",\n      tokenHash,\n      ttdStr\n    ];\n\n    sheetPengajuan.appendRow(newRow);\n\n    let sheetRiwayat = ss.getSheetByName(\"RiwayatStatus\");\n    if (sheetRiwayat) {\n      sheetRiwayat.appendRow([\n        \"RWY-\" + Utilities.getUuid().slice(0, 8),\n        idPengajuan,\n        \"-\",\n        initialStatus,\n        \"Permohonan izin baru diajukan oleh orang tua/wali\",\n        timestampStr,\n        \"Sistem (Orang Tua)\"\n      ]);\n    }\n\n    return {\n      success: true,\n      message: \"Permohonan izin berhasil diajukan dan tercatat di sistem SDN 004 Sebatik Tengah.\",\n      data: {\n        id: idPengajuan,\n        idPengajuan: idPengajuan,\n        tokenVerifikasi: plainToken,\n        tokenVerifikasiPlain: plainToken,\n        namaSiswa: data.namaSiswa,\n        kelas: data.kelas,\n        status: initialStatus,\n        timestamp: timestampStr\n      }\n    };\n  } catch (err) {\n    return {\n      success: false,\n      message: \"Gagal menyimpan pengajuan ke spreadsheet: \" + err.toString()\n    };\n  }\n}\n\n/**\n * CEK STATUS PENGAJUAN\n */\nfunction cekStatusPengajuan(id, token) {\n  try {\n    if (!id || !token) {\n      return {\n        success: false,\n        message: \"Nomor pengajuan dan kode verifikasi wajib diisi.\"\n      };\n    }\n\n    const ss = getSpreadsheet();\n    pastikanStrukturSheet(ss);\n    const sheet = ss.getSheetByName(\"PengajuanIzin\");\n    if (!sheet) {\n      return { success: false, message: \"Database pengajuan belum siap.\" };\n    }\n\n    const data = sheet.getDataRange().getValues();\n    if (data.length <= 1) {\n      return { success: false, message: \"Pengajuan tidak ditemukan di database.\" };\n    }\n\n    const inputHash = hashToken(token);\n    let matched = null;\n\n    for (let i = 1; i < data.length; i++) {\n      const row = data[i];\n      const rowId = String(row[0]).trim();\n      const rowHash = String(row[18]).trim();\n\n      if (rowId.toLowerCase() === String(id).trim().toLowerCase()) {\n        if (rowHash === inputHash || String(row[18]) === String(token).trim()) {\n          matched = {\n            id: row[0],\n            timestamp: row[1],\n            namaSiswa: row[2],\n            nisn: row[3],\n            kelas: row[4],\n            namaOrangTua: row[5],\n            nomorWhatsApp: row[6],\n            jenisIzin: row[7],\n            tanggalMulai: row[8],\n            tanggalSelesai: row[9],\n            jamKeluar: row[10],\n            alasan: row[11],\n            keterangan: row[12],\n            status: row[14],\n            catatanAdmin: row[15],\n            waktuKeputusan: row[16],\n            diprosesOleh: row[17],\n            tandaTangan: row[19] || \"\"\n          };\n          break;\n        } else {\n          return {\n            success: false,\n            message: \"Kode PIN verifikasi salah. Mohon periksa kembali 6 digit kode yang tercantum saat pendaftaran.\"\n          };\n        }\n      }\n    }\n\n    if (!matched) {\n      return {\n        success: false,\n        message: \"Pengajuan dengan nomor \" + id + \" tidak ditemukan.\"\n      };\n    }\n\n    return {\n      success: true,\n      message: \"Data pengajuan berhasil ditemukan.\",\n      data: matched\n    };\n  } catch (err) {\n    return {\n      success: false,\n      message: \"Kesalahan saat memeriksa status: \" + err.toString()\n    };\n  }\n}\n\n/**\n * DASHBOARD ADMIN & STATISTIK\n */\nfunction getAdminDashboard(filter) {\n  try {\n    const ss = getSpreadsheet();\n    pastikanStrukturSheet(ss);\n    const sheet = ss.getSheetByName(\"PengajuanIzin\");\n    if (!sheet) {\n      return { success: false, message: \"Sheet pengajuan tidak ditemukan.\" };\n    }\n\n    const rows = sheet.getDataRange().getValues();\n    const items = [];\n    const stats = {\n      total: 0,\n      hariIni: 0,\n      menunggu: 0,\n      diproses: 0,\n      disetujui: 0,\n      ditolak: 0,\n      perluPerbaikan: 0\n    };\n\n    const todayStr = Utilities.formatDate(new Date(), DEFAULT_TIMEZONE, \"yyyy-MM-dd\");\n\n    for (let i = 1; i < rows.length; i++) {\n      const r = rows[i];\n      if (!r[0]) continue;\n\n      const itemDateStr = String(r[1]).slice(0, 10);\n      const status = String(r[14]);\n\n      stats.total++;\n      if (itemDateStr === todayStr) stats.hariIni++;\n      if (status === \"Menunggu Verifikasi\") stats.menunggu++;\n      else if (status === \"Sedang Diproses\") stats.diproses++;\n      else if (status === \"Disetujui\") stats.disetujui++;\n      else if (status === \"Ditolak\") stats.ditolak++;\n      else if (status === \"Perlu Perbaikan\") stats.perluPerbaikan++;\n\n      items.push({\n        id: r[0],\n        timestamp: r[1],\n        namaSiswa: r[2],\n        nisn: r[3],\n        kelas: r[4],\n        namaOrangTua: r[5],\n        nomorWhatsApp: r[6],\n        jenisIzin: r[7],\n        tanggalMulai: r[8],\n        tanggalSelesai: r[9],\n        jamKeluar: r[10],\n        alasan: r[11],\n        keterangan: r[12],\n        filePendukung: r[13],\n        status: r[14],\n        catatanAdmin: r[15],\n        waktuKeputusan: r[16],\n        diprosesOleh: r[17],\n        tandaTangan: r[19] || \"\"\n      });\n    }\n\n    return {\n      success: true,\n      message: \"Dashboard berhasil dimuat\",\n      data: {\n        stats: stats,\n        statistik: stats,\n        items: items\n      }\n    };\n  } catch (err) {\n    return {\n      success: false,\n      message: \"Gagal memuat dashboard: \" + err.toString()\n    };\n  }\n}\n\n/**\n * DETAIL PENGAJUAN BESERTA RIWAYAT LENGKAP\n */\nfunction getDetailPengajuan(id) {\n  try {\n    const ss = getSpreadsheet();\n    pastikanStrukturSheet(ss);\n    const sheetPengajuan = ss.getSheetByName(\"PengajuanIzin\");\n    const dataP = sheetPengajuan.getDataRange().getValues();\n\n    let pengajuan = null;\n    for (let i = 1; i < dataP.length; i++) {\n      if (String(dataP[i][0]).toLowerCase() === String(id).toLowerCase()) {\n        const r = dataP[i];\n        pengajuan = {\n          id: r[0],\n          timestamp: r[1],\n          namaSiswa: r[2],\n          nisn: r[3],\n          kelas: r[4],\n          namaOrangTua: r[5],\n          nomorWhatsApp: r[6],\n          jenisIzin: r[7],\n          tanggalMulai: r[8],\n          tanggalSelesai: r[9],\n          jamKeluar: r[10],\n          alasan: r[11],\n          keterangan: r[12],\n          filePendukung: r[13],\n          status: r[14],\n          catatanAdmin: r[15],\n          waktuKeputusan: r[16],\n          diprosesOleh: r[17],\n          tandaTangan: r[19] || \"\"\n        };\n        break;\n      }\n    }\n\n    if (!pengajuan) {\n      return { success: false, message: \"Pengajuan \" + id + \" tidak ditemukan.\" };\n    }\n\n    const sheetRiwayat = ss.getSheetByName(\"RiwayatStatus\");\n    const riwayatList = [];\n    if (sheetRiwayat) {\n      const dataR = sheetRiwayat.getDataRange().getValues();\n      for (let j = 1; j < dataR.length; j++) {\n        if (String(dataR[j][1]).toLowerCase() === String(id).toLowerCase()) {\n          riwayatList.push({\n            idRiwayat: dataR[j][0],\n            idPengajuan: dataR[j][1],\n            statusSebelumnya: dataR[j][2],\n            statusBaru: dataR[j][3],\n            catatan: dataR[j][4],\n            waktuPerubahan: dataR[j][5],\n            adminPemroses: dataR[j][6]\n          });\n        }\n      }\n    }\n\n    return {\n      success: true,\n      data: {\n        pengajuan: pengajuan,\n        riwayat: riwayatList\n      }\n    };\n  } catch (err) {\n    return {\n      success: false,\n      message: \"Gagal mengambil detail: \" + err.toString()\n    };\n  }\n}\n\n/**\n * UPDATE STATUS PENGAJUAN OLEH ADMIN\n */\nfunction updateStatusPengajuan(id, status, catatan, adminNama) {\n  try {\n    const ss = getSpreadsheet();\n    pastikanStrukturSheet(ss);\n    const sheet = ss.getSheetByName(\"PengajuanIzin\");\n    if (!sheet) return { success: false, message: \"Sheet tidak ditemukan.\" };\n\n    const data = sheet.getDataRange().getValues();\n    let rowIndex = -1;\n    let oldStatus = \"-\";\n\n    for (let i = 1; i < data.length; i++) {\n      if (String(data[i][0]).toLowerCase() === String(id).toLowerCase()) {\n        rowIndex = i + 1;\n        oldStatus = String(data[i][14]);\n        break;\n      }\n    }\n\n    if (rowIndex === -1) {\n      return { success: false, message: \"ID Pengajuan tidak ditemukan: \" + id };\n    }\n\n    const now = new Date();\n    const timestampStr = Utilities.formatDate(now, DEFAULT_TIMEZONE, \"yyyy-MM-dd HH:mm:ss\");\n\n    sheet.getRange(rowIndex, 15).setValue(status);\n    sheet.getRange(rowIndex, 16).setValue(catatan || \"-\");\n    sheet.getRange(rowIndex, 17).setValue(timestampStr);\n    sheet.getRange(rowIndex, 18).setValue(adminNama || \"Admin Sekolah\");\n\n    const sheetRiwayat = ss.getSheetByName(\"RiwayatStatus\");\n    if (sheetRiwayat) {\n      sheetRiwayat.appendRow([\n        \"RWY-\" + Utilities.getUuid().slice(0, 8),\n        id,\n        oldStatus,\n        status,\n        catatan || \"Perubahan status oleh admin\",\n        timestampStr,\n        adminNama || \"Admin Sekolah\"\n      ]);\n    }\n\n    return {\n      success: true,\n      message: \"Status pengajuan \" + id + \" berhasil diperbarui menjadi: \" + status,\n      data: {\n        id: id,\n        statusBaru: status,\n        waktuKeputusan: timestampStr,\n        adminPemroses: adminNama\n      }\n    };\n  } catch (err) {\n    return {\n      success: false,\n      message: \"Gagal memperbarui status: \" + err.toString()\n    };\n  }\n}\n\n/**\n * EXPORT DATA PENGAJUAN\n */\nfunction exportData(filter) {\n  try {\n    const ss = getSpreadsheet();\n    pastikanStrukturSheet(ss);\n    const sheet = ss.getSheetByName(\"PengajuanIzin\");\n    const data = sheet.getDataRange().getValues();\n    return {\n      success: true,\n      data: data\n    };\n  } catch (err) {\n    return {\n      success: false,\n      message: \"Gagal ekspor data: \" + err.toString()\n    };\n  }\n}\n\n/**\n * MENGAMBIL PENGATURAN SEKOLAH DARI SHEET 3\n */\nfunction getPengaturan() {\n  const defaultCfg = {\n    namaSekolah: \"SDN 004 Sebatik Tengah\",\n    alamatSekolah: \"Desa Sungai Limau, Kecamatan Sebatik Tengah, Kabupaten Nunukan, Kalimantan Utara\",\n    namaKepalaSekolah: \"H. Basir, S.Pd., M.Pd.\",\n    nipKepalaSekolah: \"19780512 200502 1 003\",\n    emailSekolah: \"sdn004sebatiktengah@gmail.com\",\n    nomorKontakSekolah: \"+62 822-5555-0040\",\n    tahunAjaran: \"2026/2027\",\n    zonaWaktu: DEFAULT_TIMEZONE\n  };\n\n  try {\n    const ss = getSpreadsheet();\n    pastikanStrukturSheet(ss);\n    const sheet = ss.getSheetByName(\"Pengaturan\");\n    if (!sheet || sheet.getLastRow() <= 1) {\n      return defaultCfg;\n    }\n\n    const row = sheet.getRange(2, 1, 1, 8).getValues()[0];\n    return {\n      namaSekolah: row[0] || defaultCfg.namaSekolah,\n      alamatSekolah: row[1] || defaultCfg.alamatSekolah,\n      namaKepalaSekolah: row[2] || defaultCfg.namaKepalaSekolah,\n      nipKepalaSekolah: row[3] || defaultCfg.nipKepalaSekolah,\n      emailSekolah: row[4] || defaultCfg.emailSekolah,\n      nomorKontakSekolah: row[5] || defaultCfg.nomorKontakSekolah,\n      tahunAjaran: row[6] || defaultCfg.tahunAjaran,\n      zonaWaktu: row[7] || defaultCfg.zonaWaktu\n    };\n  } catch (err) {\n    return defaultCfg;\n  }\n}\n\n/**\n * MENYIMPAN PENGATURAN KEPALA SEKOLAH & NIP KE SHEET 3\n */\nfunction simpanPengaturan(data) {\n  try {\n    const ss = getSpreadsheet();\n    pastikanStrukturSheet(ss);\n    const sheet = ss.getSheetByName(\"Pengaturan\");\n\n    if (sheet.getLastRow() <= 1) {\n      sheet.appendRow([\n        data.namaSekolah || \"SDN 004 Sebatik Tengah\",\n        data.alamatSekolah || \"Desa Sungai Limau, Kecamatan Sebatik Tengah, Kabupaten Nunukan, Kalimantan Utara\",\n        data.namaKepalaSekolah || \"H. Basir, S.Pd., M.Pd.\",\n        data.nipKepalaSekolah || \"19780512 200502 1 003\",\n        data.emailSekolah || \"sdn004sebatiktengah@gmail.com\",\n        data.nomorKontakSekolah || \"+62 822-5555-0040\",\n        data.tahunAjaran || \"2026/2027\",\n        data.zonaWaktu || DEFAULT_TIMEZONE\n      ]);\n    } else {\n      if (data.namaKepalaSekolah) sheet.getRange(2, 3).setValue(String(data.namaKepalaSekolah).trim());\n      if (data.nipKepalaSekolah) sheet.getRange(2, 4).setValue(String(data.nipKepalaSekolah).trim());\n      if (data.namaSekolah) sheet.getRange(2, 1).setValue(String(data.namaSekolah).trim());\n      if (data.alamatSekolah) sheet.getRange(2, 2).setValue(String(data.alamatSekolah).trim());\n    }\n\n    return {\n      success: true,\n      message: \"Data Kepala Sekolah & NIP berhasil disimpan ke Google Sheets.\",\n      data: getPengaturan()\n    };\n  } catch (err) {\n    return {\n      success: false,\n      message: \"Gagal menyimpan pengaturan: \" + err.toString()\n    };\n  }\n}\n\n/**\n * SETUP OTOMATIS STRUKTUR GOOGLE SHEETS\n */\nfunction setupSpreadsheet() {\n  const ss = getSpreadsheet();\n\n  // 1. Sheet: PengajuanIzin\n  let sheet1 = ss.getSheetByName(\"PengajuanIzin\");\n  if (!sheet1) {\n    sheet1 = ss.insertSheet(\"PengajuanIzin\");\n  }\n  const headers1 = [\n    \"ID_Pengajuan\", \"Timestamp\", \"Nama_Siswa\", \"NISN\", \"Kelas\",\n    \"Nama_Orang_Tua\", \"Nomor_WhatsApp\", \"Jenis_Izin\", \"Tanggal_Mulai\", \"Tanggal_Selesai\",\n    \"Jam_Keluar\", \"Alasan\", \"Keterangan\", \"File_Pendukung\", \"Status\",\n    \"Catatan_Admin\", \"Waktu_Keputusan\", \"Diproses_Oleh\", \"Token_Verifikasi_Hash\", \"Tanda_Tangan_Orang_Tua\"\n  ];\n  sheet1.getRange(1, 1, 1, headers1.length).setValues([headers1]);\n  sheet1.getRange(1, 1, 1, headers1.length)\n    .setBackground(\"#0F52BA\")\n    .setFontColor(\"#FFFFFF\")\n    .setFontWeight(\"bold\");\n  sheet1.setFrozenRows(1);\n\n  // 2. Sheet: RiwayatStatus\n  let sheet2 = ss.getSheetByName(\"RiwayatStatus\");\n  if (!sheet2) {\n    sheet2 = ss.insertSheet(\"RiwayatStatus\");\n  }\n  const headers2 = [\n    \"ID_Riwayat\", \"ID_Pengajuan\", \"Status_Sebelumnya\", \"Status_Baru\",\n    \"Catatan\", \"Waktu_Perubahan\", \"Admin_Pemroses\"\n  ];\n  sheet2.getRange(1, 1, 1, headers2.length).setValues([headers2]);\n  sheet2.getRange(1, 1, 1, headers2.length)\n    .setBackground(\"#0F52BA\")\n    .setFontColor(\"#FFFFFF\")\n    .setFontWeight(\"bold\");\n  sheet2.setFrozenRows(1);\n\n  // 3. Sheet: Pengaturan\n  let sheet3 = ss.getSheetByName(\"Pengaturan\");\n  if (!sheet3) {\n    sheet3 = ss.insertSheet(\"Pengaturan\");\n  }\n  const headers3 = [\n    \"Nama_Sekolah\", \"Alamat_Sekolah\", \"Nama_Kepala_Sekolah\", \"NIP_Kepala_Sekolah\",\n    \"Email_Sekolah\", \"Nomor_Kontak_Sekolah\", \"Tahun_Ajaran\", \"Zona_Waktu\"\n  ];\n  sheet3.getRange(1, 1, 1, headers3.length).setValues([headers3]);\n  sheet3.getRange(1, 1, 1, headers3.length)\n    .setBackground(\"#0F52BA\")\n    .setFontColor(\"#FFFFFF\")\n    .setFontWeight(\"bold\");\n  sheet3.setFrozenRows(1);\n\n  if (sheet3.getLastRow() === 1) {\n    sheet3.appendRow([\n      \"SDN 004 Sebatik Tengah\",\n      \"Desa Sungai Limau, Kecamatan Sebatik Tengah, Kabupaten Nunukan, Kalimantan Utara\",\n      \"H. Basir, S.Pd., M.Pd.\",\n      \"19780512 200502 1 003\",\n      \"sdn004sebatiktengah@gmail.com\",\n      \"+62 822-5555-0040\",\n      \"2026/2027\",\n      DEFAULT_TIMEZONE\n    ]);\n  }\n\n  Logger.log(\"Struktur Google Sheets SIPOS berhasil disiapkan!\");\n}\n";

